// Generated: the brand faces, static instances (latin subset) of Manrope and
// Sora, base64-encoded so the function needs no static-file config to find
// them. SIL Open Font License 1.1 -- see ios/Sources/EnergyCourtage/Resources/Fonts.
// Embedded fonts are also what PDF/A-3 (and so Factur-X) requires.

export const manropeRegular = "";
export const manropeBold = "";
export const soraSemiBold = "";

export function fontBytes(b64: string): Uint8Array {
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}
